  private createWoodenShieldBitmap(): SpriteBitmap {
    const data = new Uint8ClampedArray(SPRITE_BASE_SIZE * SPRITE_BASE_SIZE * 4);
    const outline: RGBA = [24, 20, 26, 255];
    const ironRim: RGBA = [148, 160, 182, 255];
    const oak: RGBA = [154, 96, 48, 255];
    const oakDark: RGBA = [118, 70, 34, 255];
    const bossLight: RGBA = [226, 234, 248, 255];

    fillRect(data, 8, 26, 16, 2, [0, 0, 0, 110]);
    for (let y = 6; y <= 25; y++) {
      for (let x = 6; x <= 25; x++) {
        const dx = x - 15.5;
        const dy = y - 15.5;
        const distSq = dx * dx + dy * dy;
        if (distSq <= 95) {
          if (distSq > 74) {
            setPixel(data, x, y, outline);
          } else if (distSq > 54) {
            setPixel(data, x, y, ironRim);
          } else if (distSq <= 10) {
            setPixel(data, x, y, bossLight);
          } else {
            setPixel(data, x, y, x % 4 === 0 ? oakDark : oak);
          }
        }
      }
    }
    return { width: 32, height: 32, data };
  }

