  private createWardingAmuletBitmap(): SpriteBitmap {
    const data = new Uint8ClampedArray(SPRITE_BASE_SIZE * SPRITE_BASE_SIZE * 4);
    const outline: RGBA = [22, 24, 38, 255];
    const silverChain: RGBA = [192, 206, 228, 255];
    const bezelSilver: RGBA = [226, 234, 248, 255];
    const sapphire: RGBA = [56, 138, 252, 255];
    const sapphireGlow: RGBA = [164, 220, 255, 255];

    // Chain loop
    for (let i = 0; i < 7; i++) {
      setPixel(data, 11 - Math.floor(i / 3), 7 + i, silverChain);
      setPixel(data, 20 + Math.floor(i / 3), 7 + i, silverChain);
    }
    setPixel(data, 12, 14, silverChain);
    setPixel(data, 19, 14, silverChain);
    setPixel(data, 13, 15, silverChain);
    setPixel(data, 18, 15, silverChain);

    // Pendant medallion
    fillRect(data, 11, 15, 10, 10, outline);
    fillRect(data, 12, 16, 8, 8, bezelSilver);
    fillRect(data, 13, 17, 6, 6, sapphire);
    fillRect(data, 14, 18, 2, 2, sapphireGlow);
    return { width: 32, height: 32, data };
  }

  private createRingStrengthBitmap(): SpriteBitmap {
    const data = new Uint8ClampedArray(SPRITE_BASE_SIZE * SPRITE_BASE_SIZE * 4);
    const outline: RGBA = [32, 20, 18, 255];
    const goldBand: RGBA = [238, 186, 54, 255];
    const goldLight: RGBA = [255, 232, 132, 255];
    const ruby: RGBA = [228, 42, 58, 255];
    const rubyGlow: RGBA = [255, 156, 168, 255];

    for (let y = 10; y <= 24; y++) {
      for (let x = 9; x <= 22; x++) {
        const dx = x - 15.5;
        const dy = y - 17.5;
        const distSq = dx * dx + dy * dy;
        if (distSq >= 14 && distSq <= 38) {
          setPixel(data, x, y, distSq > 30 || distSq < 18 ? outline : goldBand);
        }
      }
    }
    setPixel(data, 12, 15, goldLight);
    // Ruby setting on top
    fillRect(data, 13, 7, 6, 6, outline);
    fillRect(data, 14, 8, 4, 4, ruby);
    setPixel(data, 14, 8, rubyGlow);
    return { width: 32, height: 32, data };
  }

